/** All vocabulary token ids, ready for a u32[] Sandblaster buffer. */
export const LFM2_TOKEN_IDS: number[] = Array.from(
  { length: LFM2_CONFIG.vocabSize },
  (_, tokenId) => tokenId,
);

export const lfm2 = {
  gguf: LFM2_GGUF,
  config: LFM2_CONFIG,
  tokenizer: LFM2_TOKENIZER,
  tensors: LFM2_TENSORS,
  requiredTensors: LFM2_REQUIRED_TENSORS,
  getTokens(): number[] {
    return LFM2_TOKEN_IDS;
  },
  getVocabulary(): string[] {
    return LFM2_TOKENIZER.tokens;
  },
};
